const query = $input.first().json.query || {};
const code = query.code || '';
const telegram_id = query.state || '';

if (!code) throw new Error('Missing OAuth code in callback');
if (!telegram_id) throw new Error('Missing state (telegram_id) in callback');

return [{ json: { code, telegram_id } }];

const tokenData = $input.first().json;
const extractNode = $('Extract Params').first().json;

if (!tokenData.refresh_token) {
  throw new Error('No refresh_token returned. Ensure prompt=consent was set in the OAuth URL.');
}

const expiryMs = Date.now() + (tokenData.expires_in || 3600) * 1000;
const token_expiry = new Date(expiryMs).toISOString();

return [{
  json: {
    telegram_id: extractNode.telegram_id,
    access_token: tokenData.access_token,
    refresh_token: tokenData.refresh_token,
    token_expiry,
    scope: tokenData.scope || ''
  }
}];
